/**
 * `agent/schedules/*.ts`: cron-driven runs.
 */
import { readFile } from "node:fs/promises";
import { basename, extname, relative } from "node:path";
import { getDefinitionKind } from "../brand.js";
import { isValidCron } from "../cron.js";
import { parseFrontmatter } from "../frontmatter.js";
import { displayPath } from "./context.js";
import { isDirectory, isModuleFile, toPosix, walkFiles } from "./fs.js";
import { importDefault } from "./modules.js";
export async function loadSchedules(ctx, schedulesDir, onDisable) {
    if (!(await isDirectory(schedulesDir))) {
        return [];
    }
    const schedules = [];
    for (const filePath of await walkFiles(schedulesDir)) {
        const rel = toPosix(relative(schedulesDir, filePath));
        if (rel.endsWith(".md")) {
            const name = rel.slice(0, -".md".length);
            if (name.includes("__")) {
                ctx.diagnostics.push({
                    severity: "error",
                    path: displayPath(ctx, filePath),
                    message: `Schedule name "${name}" may not contain "__"; it is reserved for extension contributions (\`<ns>__<name>\`).`,
                });
                continue;
            }
            const { data, body } = parseFrontmatter(await readFile(filePath, "utf8"));
            const cron = data.cron;
            if (cron === undefined || !isValidCron(cron)) {
                ctx.diagnostics.push({
                    severity: "error",
                    path: displayPath(ctx, filePath),
                    message: cron === undefined
                        ? "Markdown schedules require `cron` frontmatter."
                        : `Invalid cron expression: "${cron}".`,
                });
                continue;
            }
            const markdown = body.trim();
            if (markdown === "") {
                ctx.diagnostics.push({
                    severity: "error",
                    path: displayPath(ctx, filePath),
                    message: "Markdown schedules require a non-empty prompt body.",
                });
                continue;
            }
            schedules.push({
                name,
                cron,
                kind: "markdown",
                definition: {
                    __agentServe: "schedule",
                    cron,
                    markdown,
                },
            });
            continue;
        }
        if (!isModuleFile(basename(filePath))) {
            continue;
        }
        const name = rel.slice(0, -extname(rel).length);
        if (name.includes("__")) {
            ctx.diagnostics.push({
                severity: "error",
                path: displayPath(ctx, filePath),
                message: `Schedule name "${name}" may not contain "__"; it is reserved for extension contributions (\`<ns>__<name>\`).`,
            });
            continue;
        }
        const definition = await importDefault(ctx, filePath, onDisable === undefined ? "schedule" : ["schedule", "disabled"]);
        if (definition === undefined) {
            continue;
        }
        if (getDefinitionKind(definition) === "disabled") {
            onDisable?.(name, filePath);
            continue;
        }
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the loader already checked this definition brand; importDefault returns unknown
        const schedule = definition;
        if ((schedule.markdown === undefined) === (schedule.run === undefined)) {
            ctx.diagnostics.push({
                severity: "error",
                path: displayPath(ctx, filePath),
                message: "Schedules require exactly one of `markdown` or `run`.",
            });
            continue;
        }
        if (!isValidCron(schedule.cron)) {
            ctx.diagnostics.push({
                severity: "error",
                path: displayPath(ctx, filePath),
                message: `Invalid cron expression: "${schedule.cron}".`,
            });
            continue;
        }
        schedules.push({
            name,
            cron: schedule.cron,
            kind: schedule.run === undefined ? "markdown" : "run",
            definition: schedule,
        });
    }
    return schedules;
}
